const TWINS = {
// ---------------- Week 1 ----------------
w1entityTypes: { lang: "jdl",
  title: "a library borrower",
  sol: "entity Borrower {\n  fullName String,\n  joined LocalDate,\n  loans Integer,\n  overdue Boolean,\n  balance BigDecimal\n}",
  checks: [["entities", "Borrower"], ["fields Borrower", "fullName String, joined LocalDate, loans Integer, overdue Boolean, balance BigDecimal"]],
  write: { task: "Write a JDL entity `Borrower` with these fields, in this order: `fullName` (text), `joined` (a date with no time), `loans` (a whole number), `overdue` (true or false) and `balance` (an exact money amount). Use each of the JDL types `String`, `Integer`, `LocalDate`, `Boolean` and `BigDecimal` once. No validations.", starter: "entity Borrower {\n" },
  fill: { code: "entity Borrower {\n  fullName String,\n  joined LocalDate,\n  loans ___,\n  overdue ___,\n  balance BigDecimal\n}", blanks: [["Integer"], ["Boolean"]] },
  predict: { code: "entity Song {\n  name String,\n  plays Long,\n  rating Double\n}", expr: "fields Song", ask: "What does `fields Song` list? Write each field as `name Type`, separated by commas, in order." },
  explain: "Each line inside an entity is `fieldName Type`. `Integer` holds whole numbers, `Boolean` holds true or false, `LocalDate` a date with no time and `BigDecimal` an exact decimal such as a balance." },

w1validations: { lang: "jdl",
  title: "hotel rooms",
  sol: "entity HotelRoom {\n  number String required unique maxlength(4),\n  floor Integer required min(0) max(20),\n  beds Integer min(1)\n}",
  checks: [["fields HotelRoom", "number String required unique maxlength(4), floor Integer required min(0) max(20), beds Integer min(1)"]],
  write: { task: "Write a JDL entity `HotelRoom` with these fields, in this order: `number` (String: required, unique, at most 4 characters long), `floor` (Integer: required, from 0 to 20) and `beds` (Integer: at least 1). Write each field's validations in the order given.", starter: "entity HotelRoom {\n" },
  fill: { code: "entity HotelRoom {\n  number String required unique maxlength(4),\n  floor Integer required ___(0) ___(20),\n  beds Integer min(1)\n}", blanks: [["min"], ["max"]] },
  predict: { code: "entity Coupon {\n  code String unique minlength(6),\n  discount Integer max(50)\n}", expr: "fields Coupon", ask: "What does `fields Coupon` list? Write each field as `name Type validations`, separated by commas, in order." },
  explain: "`min` and `max` limit the value of a number, so `floor` must be between 0 and 20. For a String you limit its length instead, with `minlength` and `maxlength`." },

w1enum: { lang: "jdl",
  title: "pizza sizes",
  sol: "enum Size {\n  SMALL,\n  MEDIUM,\n  LARGE\n}\n\nentity Pizza {\n  name String required,\n  size Size required\n}",
  checks: [["entities", "Pizza"], ["fields Pizza", "name String required, size Size required"]],
  write: { task: "Write an enum `Size` with the values `SMALL`, `MEDIUM` and `LARGE`. Then write an entity `Pizza` with, in this order, a required `name` (String) and a required `size` whose type is `Size`.", starter: "enum Size {\n" },
  fill: { code: "___ Size {\n  SMALL,\n  MEDIUM,\n  LARGE\n}\n\nentity Pizza {\n  name String required,\n  size ___ required\n}", blanks: [["enum"], ["Size"]] },
  predict: { code: "enum Fuel {\n  PETROL,\n  ELECTRIC\n}\n\nentity Car {\n  model String,\n  fuel Fuel\n}", expr: "fields Car", ask: "What does `fields Car` list? Write each field as `name Type`, separated by commas, in order." },
  explain: "The enum's name becomes a type you can give a field, just like `String`. A pizza's `size` can then only be `SMALL`, `MEDIUM` or `LARGE`." },

w1oneToOne: { lang: "jdl",
  title: "patients and records",
  sol: "entity Patient {\n  fullName String required\n}\n\nentity MedicalRecord {\n  recordNumber String required unique\n}\n\nrelationship OneToOne {\n  Patient{record} to MedicalRecord{patient}\n}",
  checks: [["entities", "MedicalRecord, Patient"], ["relationships", "OneToOne Patient{record} to MedicalRecord{patient}"]],
  write: { task: "Write JDL for `Patient` (a required `fullName` String) and `MedicalRecord` (a `recordNumber` String that is required and unique). Each patient has exactly one record and each record belongs to one patient. Make it bidirectional and write it from `Patient` to `MedicalRecord`: `Patient` gets the field `record` and `MedicalRecord` gets the field `patient`.", starter: "entity Patient {\n" },
  fill: { code: "entity Patient {\n  fullName String required\n}\n\nentity MedicalRecord {\n  recordNumber String required unique\n}\n\nrelationship ___ {\n  Patient{___} to MedicalRecord{patient}\n}", blanks: [["OneToOne"], ["record"]] },
  predict: { code: "entity Phone {\n  model String\n}\n\nentity Sim {\n  number String\n}\n\nrelationship OneToOne {\n  Phone{sim} to Sim{phone}\n}", expr: "relationships", ask: "What does the `relationships` check print? Write it as `Type From{field} to To{field}`." },
  explain: "One on each side is `OneToOne`. With a name on both sides the link works both ways: `patient.getRecord()` and `record.getPatient()`. Leave one name out and only the named side can navigate." },

w1manyToOne: { lang: "jdl",
  title: "pets and owners",
  sol: "entity Owner {\n  email String required unique\n}\n\nentity Pet {\n  name String required\n}\n\nrelationship ManyToOne {\n  Pet{owner} to Owner\n}",
  checks: [["entities", "Owner, Pet"], ["relationships", "ManyToOne Pet{owner} to Owner"]],
  write: { task: "Write JDL for `Owner` (an `email` String that is required and unique) and `Pet` (a required `name` String). Many pets belong to one owner. Make it unidirectional from `Pet` to `Owner`: only `Pet` gets a field, called `owner`.", starter: "entity Owner {\n" },
  fill: { code: "entity Owner {\n  email String required unique\n}\n\nentity Pet {\n  name String required\n}\n\nrelationship ___ {\n  Pet{___} to Owner\n}", blanks: [["ManyToOne"], ["owner"]] },
  predict: { code: "entity Album {\n  title String\n}\n\nentity Track {\n  title String\n}\n\nrelationship ManyToOne {\n  Track{album} to Album\n}", expr: "fields Album", ask: "What does `fields Album` list? Write each field as `name Type`." },
  explain: "`Pet{owner} to Owner` reads: many pets, one owner, and only a pet can find its owner. A relationship never shows up in either entity's field list, so `Album` still has only `title`." },

w1oneToMany: { lang: "jdl",
  title: "hospitals and wards",
  sol: "entity Hospital {\n  name String required unique\n}\n\nentity Ward {\n  beds Integer required min(1)\n}\n\nrelationship OneToMany {\n  Hospital{wards} to Ward{hospital}\n}",
  checks: [["entities", "Hospital, Ward"], ["relationships", "OneToMany Hospital{wards} to Ward{hospital}"]],
  write: { task: "Write JDL for `Hospital` (a `name` String that is required and unique) and `Ward` (a `beds` Integer that is required and at least 1). One hospital has many wards and each ward is in one hospital. Write it from `Hospital` to `Ward`, with the field `wards` on `Hospital` and `hospital` on `Ward`.", starter: "entity Hospital {\n" },
  fill: { code: "entity Hospital {\n  name String required unique\n}\n\nentity Ward {\n  beds Integer required min(1)\n}\n\nrelationship ___ {\n  Hospital{wards} to Ward{___}\n}", blanks: [["OneToMany"], ["hospital"]] },
  predict: { code: "entity Farm {\n  name String\n}\n\nentity Cow {\n  tag String required,\n  born LocalDate\n}\n\nrelationship OneToMany {\n  Farm{cows} to Cow{farm}\n}", expr: "fields Cow", ask: "What does `fields Cow` list? Write each field as `name Type validations`, separated by commas, in order." },
  explain: "One hospital, many wards: the one side comes first in `OneToMany`. `hospital.getWards()` gives a list and `ward.getHospital()` gives one hospital. The ward table stores the hospital's id, but JDL does not list it as a field." },

w1manyToMany: { lang: "jdl",
  title: "playlists and songs",
  sol: "entity Playlist {\n  title String required\n}\n\nentity Song {\n  title String required\n}\n\nrelationship ManyToMany {\n  Playlist{songs} to Song{playlists}\n}",
  checks: [["entities", "Playlist, Song"], ["relationships", "ManyToMany Playlist{songs} to Song{playlists}"]],
  write: { task: "Write JDL for `Playlist` (a required `title` String) and `Song` (a required `title` String). A playlist has many songs and a song can be on many playlists. Write it from `Playlist` to `Song`, with the field `songs` on `Playlist` and `playlists` on `Song`.", starter: "entity Playlist {\n" },
  fill: { code: "entity Playlist {\n  title String required\n}\n\nentity Song {\n  title String required\n}\n\nrelationship ___ {\n  Playlist{___} to Song{playlists}\n}", blanks: [["ManyToMany"], ["songs"]] },
  predict: { code: "entity Doctor {\n  name String\n}\n\nentity Clinic {\n  city String\n}\n\nrelationship ManyToMany {\n  Doctor{clinics} to Clinic{doctors}\n}", expr: "entities", ask: "The database gets a join table for this relationship. Which entity names does the JDL declare? Write them sorted A to Z, separated by commas." },
  explain: "Both `playlist.getSongs()` and `song.getPlaylists()` return lists, so this is `ManyToMany`. The join table that links them is made for you; it is not an entity you write." },

w1noLists: { lang: "jdl",
  title: "albums and tracks",
  sol: "entity Album {\n  title String required\n}\n\nentity Track {\n  name String required,\n  seconds Integer min(1)\n}\n\nrelationship OneToMany {\n  Album{tracks} to Track{album}\n}",
  checks: [["entities", "Album, Track"], ["fields Album", "title String required"], ["relationships", "OneToMany Album{tracks} to Track{album}"]],
  write: { task: "An `Album` has a required `title` (String) and a list of tracks. Each track has a required `name` (String) and a `seconds` Integer of at least 1. JDL cannot hold a list in a field, so make `Track` an entity and link it to `Album`. Write the link from `Album` to `Track`, with the field `tracks` on `Album` and `album` on `Track`.", starter: "entity Album {\n" },
  fill: { code: "entity Album {\n  title String required\n}\n\n___ Track {\n  name String required,\n  seconds Integer min(1)\n}\n\nrelationship ___ {\n  Album{tracks} to Track{album}\n}", blanks: [["entity"], ["OneToMany"]] },
  predict: { code: "entity Garden {\n  name String\n}\n\nentity Plant {\n  species String\n}\n\nrelationship OneToMany {\n  Garden{plants} to Plant{garden}\n}", expr: "entities", ask: "A garden needs a list of plants. Which entity names does this declare? Write them sorted A to Z, separated by commas." },
  explain: "There is no `List<Track>` field in JDL. The tracks become their own entity and the `OneToMany` relationship holds the list, so `album.getTracks()` still works in the generated code." },

w1miniModel: { lang: "jdl",
  title: "galleries, paintings and artists",
  sol: "entity Gallery {\n  city String required\n}\n\nentity Painting {\n  title String required\n}\n\nentity Artist {\n  name String required unique\n}\n\nrelationship OneToMany {\n  Gallery{paintings} to Painting{gallery}\n}\n\nrelationship ManyToOne {\n  Painting{artist} to Artist\n}",
  checks: [["entities", "Artist, Gallery, Painting"], ["relationships", "ManyToOne Painting{artist} to Artist; OneToMany Gallery{paintings} to Painting{gallery}"]],
  write: { task: "Write JDL for `Gallery` (a required `city` String), `Painting` (a required `title` String) and `Artist` (a `name` String that is required and unique). A gallery holds many paintings and each painting is in one gallery: write it from `Gallery`, with `paintings` on `Gallery` and `gallery` on `Painting`. Many paintings are by one artist: make it unidirectional from `Painting` to `Artist`, with only the field `artist` on `Painting`.", starter: "entity Gallery {\n" },
  fill: { code: "entity Gallery {\n  city String required\n}\n\nentity Painting {\n  title String required\n}\n\nentity Artist {\n  name String required unique\n}\n\nrelationship ___ {\n  Gallery{paintings} to Painting{gallery}\n}\n\nrelationship ___ {\n  Painting{artist} to Artist\n}", blanks: [["OneToMany"], ["ManyToOne"]] },
  predict: { code: "entity Port\nentity Ferry\nentity Sailor\n\nrelationship ManyToOne {\n  Ferry{port} to Port\n}\n\nrelationship ManyToMany {\n  Ferry{sailors} to Sailor{ferries}\n}", expr: "fields Ferry", ask: "What does `fields Ferry` list? If it has no fields, write `(none)`." },
  explain: "Use one `relationship` block per type, each starting from the side you name first. Both links here are \"one\" on one end and \"many\" on the other, but they are written from different ends, so one is `OneToMany` and the other is `ManyToOne`." },

// ---------------- Week 2 ----------------
w2createTable: { title: "gym members table",
  sol: "CREATE TABLE member (\n  member_id SERIAL PRIMARY KEY,\n  full_name VARCHAR(60) NOT NULL,\n  phone     VARCHAR(20)\n);",
  checks: [
    ["SELECT column_name, data_type, is_nullable\nFROM information_schema.columns\nWHERE table_name = 'member'\nORDER BY ordinal_position", "member_id, integer, NO; full_name, character varying, NO; phone, character varying, YES"],
    ["SELECT column_name\nFROM information_schema.key_column_usage\nWHERE table_name = 'member'", "member_id"],
    ["SELECT column_default LIKE 'nextval%'\nFROM information_schema.columns\nWHERE table_name = 'member' AND column_name = 'member_id'", "true"]],
  write: { task: "Create a table `member` for a gym with three columns in this order: `member_id` (numbered automatically with `SERIAL`, the primary key), `full_name` (`VARCHAR(60)`, not null) and `phone` (`VARCHAR(20)`).", starter: "CREATE TABLE member (\n" },
  fill: { code: "CREATE TABLE member (\n  member_id ___ PRIMARY KEY,\n  full_name VARCHAR(60) ___,\n  phone     VARCHAR(20)\n);", blanks: [["SERIAL"], ["NOT NULL"]] },
  predict: { code: "CREATE TABLE gym_class (\n  class_id SERIAL PRIMARY KEY,\n  title    VARCHAR(40) NOT NULL,\n  coach    VARCHAR(40)\n);\n\nINSERT INTO gym_class (title) VALUES ('Yoga');\n\nSELECT coach FROM gym_class;",
    ask: "The `INSERT` gives no value for `coach`. What does the `SELECT` return? Write `null` for an empty value." },
  explain: "`SERIAL` is a whole number that PostgreSQL fills in for you: 1 for the first row, 2 for the next, and so on. `VARCHAR(60)` is text of at most 60 characters. `NOT NULL` means a member must always have a name; a column without it, like `coach`, is simply left NULL when no value is given." },

w2insert: { title: "log parcels",
  setup: "CREATE TABLE parcel (\n  parcel_id SERIAL PRIMARY KEY,\n  recipient VARCHAR(60) NOT NULL,\n  city      VARCHAR(40),\n  weight_kg NUMERIC(5,2)\n);\n\nINSERT INTO parcel (recipient, city, weight_kg)\nVALUES ('Ana Costa', 'York', 1.2);",
  sol: "INSERT INTO parcel (recipient, city, weight_kg)\nVALUES\n  ('Priya Shah', 'Leeds', 2.5),\n  ('Tom Reid', 'Bristol', 0.75);",
  checks: [["SELECT parcel_id, recipient, city, weight_kg\nFROM parcel\nORDER BY parcel_id", "1, Ana Costa, York, 1.20; 2, Priya Shah, Leeds, 2.50; 3, Tom Reid, Bristol, 0.75"]],
  write: { task: "A courier logs parcels in `parcel`. Add two parcels: first one for `Priya Shah` in `Leeds` weighing 2.5 kg, then one for `Tom Reid` in `Bristol` weighing 0.75 kg. Name the columns you fill in, and let `SERIAL` set `parcel_id`.", starter: "INSERT INTO parcel\n" },
  fill: { code: "INSERT INTO parcel (___)\nVALUES\n  ('Priya Shah', 'Leeds', 2.5),\n  ('Tom Reid', 'Bristol', 0.75);", blanks: [["recipient, city, weight_kg", "recipient,city,weight_kg"]] },
  predict: { code: "INSERT INTO parcel\nVALUES (10, 'Li Wei', 'Hull', 3);\n\nSELECT weight_kg FROM parcel WHERE parcel_id = 10;",
    ask: "There is no column list, so the values go in the table's column order. What does the `SELECT` return? Remember that `weight_kg` is `NUMERIC(5,2)`." },
  explain: "The column list says which columns the values are for, in that order, so `parcel_id` can be left to `SERIAL`. Without a list you must give every column in the table's own order. `NUMERIC(5,2)` always shows two decimal places, so 3 is stored as `3.00`." },

w2select: { title: "flights with seats",
  setup: "CREATE TABLE flight (\n  flight_no   VARCHAR(8) PRIMARY KEY,\n  origin      VARCHAR(30),\n  destination VARCHAR(30),\n  seats_free  INT\n);\n\nINSERT INTO flight VALUES\n  ('BA101', 'Manchester', 'Rome', 12),\n  ('EZ220', 'Manchester', 'Paris', 0),\n  ('RY330', 'Bristol', 'Rome', 5),\n  ('BA415', 'Manchester', 'Lisbon', 3),\n  ('KL502', 'Bristol', 'Oslo', 0);",
  sol: "SELECT flight_no, destination\nFROM flight\nWHERE origin = 'Manchester' AND seats_free > 0;",
  checks: [["@result", "BA101, Rome; BA415, Lisbon"]],
  write: { task: "Return two columns, `flight_no` then `destination`, for every flight from `Manchester` that still has free seats (`seats_free` above 0). For example, one row is `BA101, Rome`.", starter: "SELECT\n" },
  fill: { code: "___ flight_no, destination\n___ flight\nWHERE origin = 'Manchester' AND seats_free > 0;", blanks: [["SELECT"], ["FROM"]] },
  predict: { code: "SELECT *\nFROM flight\nWHERE destination = 'Oslo';" },
  explain: "`SELECT *` returns every column; naming columns returns only those, in the order you list them. `WHERE` with `AND` keeps a row only when both tests are true." },

w2update: { title: "improve a phone plan",
  setup: "CREATE TABLE phone_plan (\n  plan_id     INT PRIMARY KEY,\n  plan_name   VARCHAR(30) NOT NULL,\n  data_gb     INT,\n  monthly_fee NUMERIC(5,2)\n);\n\nINSERT INTO phone_plan VALUES\n  (1, 'Basic', 5, 8.00),\n  (2, 'Plus', 20, 15.00),\n  (3, 'Max', 100, 25.00);",
  sol: "UPDATE phone_plan\nSET data_gb = 50, monthly_fee = 18.00\nWHERE plan_id = 2;",
  checks: [["SELECT plan_id, data_gb, monthly_fee\nFROM phone_plan\nORDER BY plan_id", "1, 5, 8.00; 2, 50, 18.00; 3, 100, 25.00"]],
  write: { task: "Plan 2 is being improved. In one `UPDATE`, set its `data_gb` to 50 and its `monthly_fee` to 18.00. Leave the other plans alone.", starter: "UPDATE phone_plan\n" },
  fill: { code: "UPDATE phone_plan\n___ data_gb = 50, monthly_fee = 18.00\n___;", blanks: [["SET"], ["WHERE plan_id = 2"]] },
  predict: { code: "UPDATE phone_plan\nSET data_gb = 100;\n\nSELECT data_gb FROM phone_plan WHERE plan_id = 1;",
    ask: "This `UPDATE` has no `WHERE`. What does the `SELECT` return?" },
  explain: "One `SET` can change several columns, separated by commas. The `WHERE` limits the change to the rows you mean; leave it out and every row in the table is updated." },

w2delete: { title: "cancel short stays",
  setup: "CREATE TABLE booking (\n  booking_id INT PRIMARY KEY,\n  guest      VARCHAR(40) NOT NULL,\n  pitch      CHAR(1),\n  nights     INT\n);\n\nINSERT INTO booking VALUES\n  (1, 'Sam Holt', 'A', 1),\n  (2, 'Mia Grant', 'A', 4),\n  (3, 'Leo Park', 'B', 1),\n  (4, 'Zoe Lane', 'A', 1),\n  (5, 'Raj Iyer', 'C', 3);",
  sol: "DELETE FROM booking\nWHERE pitch = 'A' AND nights = 1;",
  checks: [["SELECT booking_id FROM booking", "2; 3; 5"]],
  write: { task: "A campsite keeps its bookings in `booking`. Delete the bookings on pitch `A` that are for 1 night. Keep every other booking.", starter: "DELETE\n" },
  fill: { code: "DELETE FROM booking\n___ pitch = 'A' AND nights = 1;", blanks: [["WHERE"]] },
  predict: { code: "DELETE FROM booking\nWHERE nights = 1 OR pitch = 'C';\n\nSELECT guest FROM booking;",
    ask: "Which guests are left after the `DELETE`? Separate rows with semicolons, like `Ann Cole; Ben Ruiz`." },
  explain: "`DELETE FROM booking WHERE ...` removes each row that matches the test. With `AND` both parts must be true; with `OR` either one is enough, so `OR` usually deletes more rows." },

w2updateAnomaly: { title: "support phone change",
  setup: "CREATE TABLE staff (\n  staff_id   INT PRIMARY KEY,\n  staff_name VARCHAR(40) NOT NULL,\n  dept       VARCHAR(20),\n  dept_phone VARCHAR(15)\n);\n\nINSERT INTO staff VALUES\n  (1, 'Omar', 'Sales', '0121 111'),\n  (2, 'Lena', 'Sales', '0121 111'),\n  (3, 'Kofi', 'Support', '0121 222'),\n  (4, 'Ruth', 'Support', '0121 222');",
  sol: "UPDATE staff\nSET dept_phone = '0121 999'\nWHERE dept = 'Support';",
  checks: [["SELECT staff_id, dept_phone\nFROM staff\nORDER BY staff_id", "1, 0121 111; 2, 0121 111; 3, 0121 999; 4, 0121 999"]],
  write: { task: "In `staff` each row repeats its department's phone number. The `Support` number is now `'0121 999'`. Write one `UPDATE` that sets `dept_phone` to it on every Support row.", starter: "UPDATE staff\n" },
  fill: { code: "UPDATE staff\nSET ___\nWHERE dept = 'Support';", blanks: [["dept_phone = '0121 999'"]] },
  predict: { code: "UPDATE staff\nSET dept_phone = '0121 999'\nWHERE staff_name = 'Kofi';\n\nSELECT staff_name, dept_phone\nFROM staff\nWHERE dept = 'Support';",
    ask: "The number was changed on Kofi's row only. What do the Support rows show now? Write each row as `name, phone`, with rows separated by semicolons." },
  explain: "The phone number belongs to the department, but it is repeated in every staff row. Updating only some of those rows leaves two different numbers for one department: an update anomaly. Storing it once in a department table avoids this." },

w2repeatingGroup: { title: "split out subjects",
  setup: "CREATE TABLE tutor (\n  tutor_id   INT PRIMARY KEY,\n  tutor_name VARCHAR(40) NOT NULL,\n  subject1   VARCHAR(30),\n  subject2   VARCHAR(30),\n  subject3   VARCHAR(30)\n);\n\nINSERT INTO tutor VALUES\n  (1, 'Ali', 'Maths', 'Physics', NULL),\n  (2, 'Bea', 'French', 'Maths', 'Spanish'),\n  (3, 'Cy', 'Art', NULL, NULL);",
  sol: "CREATE TABLE tutor_subject (\n  tutor_id INT,\n  subject  VARCHAR(30),\n  PRIMARY KEY (tutor_id, subject)\n);",
  checks: [
    ["SELECT column_name, data_type\nFROM information_schema.columns\nWHERE table_name = 'tutor_subject'\nORDER BY ordinal_position", "tutor_id, integer; subject, character varying"],
    ["SELECT k.column_name\nFROM information_schema.table_constraints t\nJOIN information_schema.key_column_usage k ON k.constraint_name = t.constraint_name\nWHERE t.table_name = 'tutor_subject' AND t.constraint_type = 'PRIMARY KEY'", "tutor_id; subject"]],
  write: { task: "A tutoring agency keeps up to three subjects per tutor in `subject1` to `subject3`, a repeating group. Create a table `tutor_subject` with two columns in this order: `tutor_id` (`INT`) and `subject` (`VARCHAR(30)`), one row per subject a tutor teaches. Choose its primary key so a tutor can teach many subjects but never the same subject twice.", starter: "CREATE TABLE tutor_subject (\n" },
  fill: { code: "CREATE TABLE tutor_subject (\n  tutor_id INT,\n  subject  VARCHAR(30),\n  PRIMARY KEY (___)\n);", blanks: [["tutor_id, subject", "tutor_id,subject", "subject, tutor_id", "subject,tutor_id"]] },
  predict: { code: "SELECT tutor_name\nFROM tutor\nWHERE subject1 = 'Maths';",
    ask: "This runs on `tutor`, before the split. Bea teaches Maths too. Which names does it return? Separate rows with semicolons if there are several." },
  explain: "With numbered columns a subject can sit in any of them, so `WHERE subject1 = 'Maths'` misses Bea, whose Maths is in `subject2`. In `tutor_subject` every subject is in the same column, so one test finds them all. The key is the pair: one tutor has many rows, but each (tutor, subject) appears only once." },

// A partial dependency (2NF). The predict shows that a split removes the insert anomaly.
w2partialDependency: { title: "rooms and stays",
  setup: "CREATE TABLE stay_flat (\n  room_no   INT,\n  night     DATE,\n  room_type VARCHAR(10),\n  guest     VARCHAR(40),\n  PRIMARY KEY (room_no, night)\n);\n\nINSERT INTO stay_flat VALUES\n  (12, '2026-05-01', 'Double', 'Ivy Moss'),\n  (12, '2026-05-02', 'Double', 'Ivy Moss'),\n  (15, '2026-05-01', 'Single', 'Tariq Aziz');",
  sol: "CREATE TABLE room (\n  room_no   INT PRIMARY KEY,\n  room_type VARCHAR(10)\n);\n\nCREATE TABLE stay (\n  room_no INT,\n  night   DATE,\n  guest   VARCHAR(40),\n  PRIMARY KEY (room_no, night)\n);",
  checks: [
    ["SELECT table_name, column_name\nFROM information_schema.columns\nWHERE table_name IN ('room', 'stay')\nORDER BY table_name, ordinal_position", "room, room_no; room, room_type; stay, room_no; stay, night; stay, guest"],
    ["SELECT t.table_name, k.column_name\nFROM information_schema.table_constraints t\nJOIN information_schema.key_column_usage k ON k.constraint_name = t.constraint_name\nWHERE t.table_name IN ('room', 'stay') AND t.constraint_type = 'PRIMARY KEY'", "room, room_no; stay, room_no; stay, night"]],
  write: { task: "A small hotel uses `stay_flat`, whose key is (`room_no`, `night`). `room_type` depends only on `room_no`, which breaks 2NF. Split it. First create `room` with `room_no` (`INT`) then `room_type` (`VARCHAR(10)`), keyed on the column that decides the type. Then create `stay` with `room_no` (`INT`), `night` (`DATE`) and `guest` (`VARCHAR(40)`), in that order, keyed on the pair (`room_no`, `night`).", starter: "CREATE TABLE room (\n" },
  fill: { code: "CREATE TABLE room (\n  room_no   INT ___,\n  room_type VARCHAR(10)\n);\n\nCREATE TABLE stay (\n  room_no INT,\n  night   DATE,\n  guest   VARCHAR(40),\n  PRIMARY KEY (___)\n);", blanks: [["PRIMARY KEY"], ["room_no, night", "room_no,night", "night, room_no", "night,room_no"]] },
  predict: { code: "CREATE TABLE room (\n  room_no   INT PRIMARY KEY,\n  room_type VARCHAR(10)\n);\n\nINSERT INTO room VALUES\n  (12, 'Double'), (15, 'Single'), (20, 'Suite');\n\nSELECT room_type\nFROM room\nWHERE room_no = 20;",
    ask: "Room 20 is new and nobody has stayed in it yet. After the split, what does the `SELECT` return?" },
  explain: "In `stay_flat` a room could only be recorded with a night, because `night` is part of the key: you could not add room 20 until someone booked it (an insert anomaly). In the `room` table each room's type is stored once, with or without stays. `stay` keeps only `guest`, which needs both the room and the night." },

w2transitive: { title: "gigs and venues",
  setup: "CREATE TABLE gig_flat (\n  gig_id         INT PRIMARY KEY,\n  band           VARCHAR(40) NOT NULL,\n  venue_name     VARCHAR(30),\n  venue_capacity INT\n);\n\nINSERT INTO gig_flat VALUES\n  (1, 'Copper Owls', 'Old Mill', 400),\n  (2, 'Velvet Foxes', 'Arena North', 5000),\n  (3, 'Glass Harbour', 'Old Mill', 400);",
  sol: "CREATE TABLE venue (\n  venue_name VARCHAR(30) PRIMARY KEY,\n  capacity   INT\n);\n\nCREATE TABLE gig (\n  gig_id     INT PRIMARY KEY,\n  band       VARCHAR(40) NOT NULL,\n  venue_name VARCHAR(30)\n);",
  checks: [
    ["SELECT table_name, column_name, is_nullable\nFROM information_schema.columns\nWHERE table_name IN ('venue', 'gig')\nORDER BY table_name, ordinal_position", "gig, gig_id, NO; gig, band, NO; gig, venue_name, YES; venue, venue_name, NO; venue, capacity, YES"],
    ["SELECT t.table_name, k.column_name\nFROM information_schema.table_constraints t\nJOIN information_schema.key_column_usage k ON k.constraint_name = t.constraint_name\nWHERE t.table_name IN ('venue', 'gig') AND t.constraint_type = 'PRIMARY KEY'\nORDER BY 1", "gig, gig_id; venue, venue_name"]],
  write: { task: "In `gig_flat`, `venue_capacity` depends on `venue_name`, not directly on `gig_id`. Split it into 3NF. First create `venue` with `venue_name` (`VARCHAR(30)`, primary key) then `capacity` (`INT`). Then create `gig` with `gig_id` (`INT`, primary key), `band` (`VARCHAR(40)`, not null) and `venue_name` (`VARCHAR(30)`), in that order.", starter: "CREATE TABLE venue (\n" },
  fill: { code: "CREATE TABLE venue (\n  venue_name VARCHAR(30) PRIMARY KEY,\n  ___ INT\n);\n\nCREATE TABLE gig (\n  gig_id     INT ___,\n  band       VARCHAR(40) NOT NULL,\n  venue_name VARCHAR(30)\n);", blanks: [["capacity"], ["PRIMARY KEY"]] },
  predict: { code: "CREATE TABLE venue (\n  venue_name VARCHAR(30) PRIMARY KEY,\n  capacity   INT\n);\n\nINSERT INTO venue VALUES\n  ('Old Mill', 400),\n  ('Arena North', 5000);\n\nSELECT venue_name\nFROM venue\nWHERE capacity > 1000;",
    ask: "After the split, what does this return? (In `gig_flat`, Old Mill's capacity was stored twice.)" },
  explain: "A transitive dependency is a chain: the gig decides the venue, and the venue decides the capacity. 3NF breaks the chain by giving the venue its own table, so each capacity is stored once. The gig keeps `venue_name` as a foreign key to find it." },

// ---------------- Week 3 ----------------
w3copyCsv: { title: "load flight times",
  setup: "CREATE TABLE flight (\n  flight_no   VARCHAR(8) PRIMARY KEY,\n  destination VARCHAR(40) NOT NULL,\n  seats       INT,\n  departs     DATE\n);",
  files: { "flights.csv": "flight_no,destination,seats,departs\nBA208,Lisbon,180,2026-12-01\nEZ114,Oslo,156,2026-12-03\nFR902,Porto,189,2026-12-03\nKL41,Amsterdam,,2026-12-05\n" },
  sol: "\\copy flight FROM 'flights.csv' WITH (FORMAT csv, HEADER true)",
  checks: [["SELECT flight_no, destination, seats, departs\nFROM flight\nORDER BY flight_no", "BA208, Lisbon, 180, 2026-12-01; EZ114, Oslo, 156, 2026-12-03; FR902, Porto, 189, 2026-12-03; KL41, Amsterdam, null, 2026-12-05"]],
  write: { task: "`flights.csv` starts with a header line, then has one flight per line, in the same order as the columns of `flight`. Load it into the empty table `flight` with psql's `\\copy`, written on one line.", starter: "\\copy flight " },
  fill: { code: "___ flight FROM 'flights.csv' WITH (___ csv, HEADER true)", blanks: [["\\copy"], ["FORMAT"]] },
  predict: { code: "\\copy flight FROM 'flights.csv' WITH (FORMAT csv, HEADER true)\n\nSELECT COUNT(*) FROM flight WHERE departs = '2026-12-03';" },
  explain: "`\\copy` is a psql command that reads a file from your computer into a table. The table must exist first, with columns in the same order as the file. `HEADER true` tells it the first line is column names, not data." },

w3addColumn: { title: "albums get a year",
  setup: "CREATE TABLE album (\n  album_id INT PRIMARY KEY,\n  title    VARCHAR(80),\n  artist   VARCHAR(60)\n);\n\nINSERT INTO album VALUES\n  (1, 'Blue', 'Joni Mitchell'),\n  (2, 'Rumours', 'Fleetwood Mac');",
  sol: "ALTER TABLE album\nADD COLUMN release_year INT;",
  checks: [
    ["SELECT column_name, data_type\nFROM information_schema.columns\nWHERE table_name = 'album'\nORDER BY ordinal_position", "album_id, integer; title, character varying; artist, character varying; release_year, integer"],
    ["SELECT COUNT(*) FROM album", "2"]],
  write: { task: "Add a whole-number column `release_year` (type `INT`) to the existing table `album`, keeping its two rows.", starter: "ALTER TABLE album\n" },
  fill: { code: "___ TABLE album\n___ release_year INT;", blanks: [["ALTER"], ["ADD COLUMN", "ADD"]] },
  predict: { code: "ALTER TABLE album\nADD COLUMN copies_sold INT DEFAULT 0;\n\nSELECT copies_sold FROM album WHERE album_id = 1;",
    ask: "This new column has `DEFAULT 0`. What does the old row for album 1 hold in it?" },
  explain: "`ALTER TABLE ... ADD COLUMN name type` adds a column to a table that already has data. Old rows get NULL in the new column, or the default if you give one." },

w3foreignKey: { title: "link songs to artists",
  setup: "CREATE TABLE artist (\n  artist_id INT PRIMARY KEY,\n  name      VARCHAR(60)\n);\n\nCREATE TABLE song (\n  song_id   INT PRIMARY KEY,\n  title     VARCHAR(80),\n  artist_id INT\n);\n\nINSERT INTO artist VALUES (1, 'Adele'), (2, 'Burna Boy');\nINSERT INTO song VALUES (1, 'Hello', 1), (2, 'Last Last', 2);",
  sol: "ALTER TABLE song\nADD CONSTRAINT fk_song_artist\nFOREIGN KEY (artist_id) REFERENCES artist (artist_id);",
  checks: [
    ["SELECT constraint_name\nFROM information_schema.table_constraints\nWHERE table_name = 'song' AND constraint_type = 'FOREIGN KEY'", "fk_song_artist"],
    ["SELECT table_name, column_name\nFROM information_schema.constraint_column_usage\nWHERE constraint_name = 'fk_song_artist'", "artist, artist_id"]],
  write: { task: "Use `ALTER TABLE` to add a foreign key named `fk_song_artist`, so that `song.artist_id` must match an `artist_id` in `artist`.", starter: "ALTER TABLE song\n" },
  fill: { code: "ALTER TABLE song\nADD CONSTRAINT fk_song_artist\n___ (artist_id) ___ artist (artist_id);", blanks: [["FOREIGN KEY"], ["REFERENCES"]] },
  predict: { code: "ALTER TABLE song\nADD CONSTRAINT fk_song_artist\nFOREIGN KEY (artist_id) REFERENCES artist (artist_id);\n\nINSERT INTO song VALUES (3, 'Demo', NULL);\n\nSELECT COUNT(*) FROM song;",
    ask: "The new song's `artist_id` is NULL. What does the count return?" },
  explain: "`FOREIGN KEY (artist_id) REFERENCES artist (artist_id)` links the two tables: PostgreSQL now refuses a song whose `artist_id` is not in `artist`. NULL is still allowed, because it means no artist is known." },

w3setDefault: { title: "normal priority",
  setup: "CREATE TABLE task (\n  task_id  INT PRIMARY KEY,\n  title    VARCHAR(60),\n  priority VARCHAR(10)\n);",
  sol: "ALTER TABLE task\nALTER COLUMN priority SET DEFAULT 'normal';",
  checks: [["INSERT INTO task (task_id, title) VALUES (1, 'Water plants');\nSELECT priority FROM task WHERE task_id = 1;", "normal"]],
  write: { task: "Change the existing table `task` so that `priority` is `'normal'` whenever a new task leaves it out.", starter: "ALTER TABLE task\n" },
  fill: { code: "___ task\nALTER COLUMN priority ___ 'normal';", blanks: [["ALTER TABLE"], ["SET DEFAULT"]] },
  predict: { code: "INSERT INTO task (task_id, title) VALUES (1, 'Pay rent');\n\nALTER TABLE task\nALTER COLUMN priority SET DEFAULT 'low';\n\nINSERT INTO task (task_id, title) VALUES (2, 'Tidy desk');\n\nSELECT task_id, priority FROM task ORDER BY task_id;",
    ask: "Task 1 was added before the default was set. What does the query return?" },
  explain: "`SET DEFAULT` gives a column a value to use when a new row leaves it out. It only affects rows added afterwards: rows that already exist keep what they had." },

w3countSum: { title: "unpaid library fines",
  setup: "CREATE TABLE fine (\n  fine_id INT PRIMARY KEY,\n  member  VARCHAR(20),\n  amount  NUMERIC(5,2),\n  paid    BOOLEAN\n);\n\nINSERT INTO fine VALUES\n  (1, 'Asha', 2.50, true),\n  (2, 'Ben', 1.00, false),\n  (3, 'Asha', 4.00, false),\n  (4, 'Cleo', 0.50, false),\n  (5, 'Ben', 3.25, false);",
  sol: "SELECT COUNT(*), SUM(amount)\nFROM fine\nWHERE paid = false;",
  checks: [["@result", "4, 8.75"]],
  write: { task: "Look only at fines with `paid = false`. Return one row with two columns: how many such fines there are, then their total `amount`.", starter: "SELECT\n" },
  fill: { code: "SELECT ___, ___(amount)\nFROM fine\nWHERE paid = false;", blanks: [["COUNT(*)", "COUNT(fine_id)"], ["SUM"]] },
  predict: { code: "SELECT SUM(amount)\nFROM fine\nWHERE member = 'Asha';" },
  explain: "Aggregate functions turn many rows into one value: `COUNT(*)` gives the number of rows and `SUM` adds a column up. `WHERE` runs first, so only unpaid fines are counted and added." },

w3minMaxAvg: { title: "Parkside room prices",
  setup: "CREATE TABLE room (\n  room_no INT PRIMARY KEY,\n  hotel   VARCHAR(30),\n  price   INT\n);\n\nINSERT INTO room VALUES\n  (101, 'Seaview', 95),\n  (102, 'Seaview', 120),\n  (201, 'Parkside', 70),\n  (202, 'Parkside', 88),\n  (203, 'Parkside', 65);",
  sol: "SELECT MIN(price), MAX(price), ROUND(AVG(price), 2)\nFROM room\nWHERE hotel = 'Parkside';",
  checks: [["@result", "65, 88, 74.33"]],
  write: { task: "For the `Parkside` hotel only, return one row with three columns in this order: the lowest `price`, the highest `price`, and the average price rounded to 2 decimal places.", starter: "SELECT\n" },
  fill: { code: "SELECT ___(price), MAX(price), ROUND(___(price), 2)\nFROM room\nWHERE hotel = 'Parkside';", blanks: [["MIN"], ["AVG"]] },
  predict: { code: "SELECT MAX(price) - MIN(price) AS price_gap\nFROM room;" },
  explain: "You can put several aggregate functions in one `SELECT`; each gives one value for the rows that `WHERE` keeps. `AVG` of whole numbers can have many decimals, so `ROUND(..., 2)` cuts it to two." },

w3groupBy: { title: "books per genre",
  setup: "CREATE TABLE book (\n  book_id INT PRIMARY KEY,\n  title   VARCHAR(60),\n  genre   VARCHAR(20)\n);\n\nINSERT INTO book VALUES\n  (1, 'Emma', 'Classic'),\n  (2, 'Dune', 'Sci-fi'),\n  (3, 'Persuasion', 'Classic'),\n  (4, 'Neuromancer', 'Sci-fi'),\n  (5, 'Middlemarch', 'Classic'),\n  (6, 'Rebecca', 'Mystery');",
  sol: "SELECT genre, COUNT(*) AS books\nFROM book\nGROUP BY genre\nORDER BY books DESC;",
  checks: [["@result", "Classic, 3; Sci-fi, 2; Mystery, 1"]],
  write: { task: "Return two columns, `genre` and how many books it has, with one row per genre and the biggest count first. For example, the first row is `Classic, 3`.", starter: "SELECT genre,\n" },
  fill: { code: "SELECT genre, COUNT(*) AS books\nFROM book\n___ genre\nORDER BY books ___;", blanks: [["GROUP BY"], ["DESC"]] },
  predict: { code: "SELECT genre\nFROM book\nGROUP BY genre\nORDER BY genre;" },
  explain: "`GROUP BY genre` makes one group for each genre, and `COUNT(*)` counts the rows in each group. `ORDER BY books DESC` sorts by that count, biggest first; `books` is the name given to the count with `AS`." },

w3whereHaving: { title: "late airlines to Paris",
  setup: "CREATE TABLE flight (\n  flight_id   INT PRIMARY KEY,\n  airline     VARCHAR(20),\n  destination VARCHAR(20),\n  delay_mins  INT\n);\n\nINSERT INTO flight VALUES\n  (1, 'SkyJet', 'Paris', 30),\n  (2, 'SkyJet', 'Paris', 10),\n  (3, 'AirLoop', 'Paris', 5),\n  (4, 'AirLoop', 'Rome', 60),\n  (5, 'AirLoop', 'Paris', 15),\n  (6, 'Northwind', 'Paris', 25),\n  (7, 'SkyJet', 'Rome', 0);",
  sol: "SELECT airline, ROUND(AVG(delay_mins), 1)\nFROM flight\nWHERE destination = 'Paris'\nGROUP BY airline\nHAVING AVG(delay_mins) > 15\nORDER BY airline;",
  checks: [["@result", "Northwind, 25.0; SkyJet, 20.0"]],
  write: { task: "Use only flights to `Paris`. Return two columns, `airline` and its average `delay_mins` rounded to 1 decimal place, for airlines whose average is more than 15, sorted by airline.", starter: "SELECT airline,\n" },
  fill: { code: "SELECT airline, ROUND(AVG(delay_mins), 1)\nFROM flight\n___ destination = 'Paris'\nGROUP BY airline\nHAVING ___(delay_mins) > 15\nORDER BY airline;", blanks: [["WHERE"], ["AVG"]] },
  predict: { code: "SELECT airline\nFROM flight\nGROUP BY airline\nHAVING MAX(delay_mins) >= 30\nORDER BY airline;" },
  explain: "`WHERE destination = 'Paris'` throws away the Rome flights before any grouping. `HAVING AVG(delay_mins) > 15` then keeps only the airlines whose group average is high enough. A condition on an aggregate always goes in `HAVING`, never in `WHERE`." },

w3join: { title: "Nigerian authors' books",
  setup: "CREATE TABLE author (\n  author_id INT PRIMARY KEY,\n  name      VARCHAR(40),\n  country   VARCHAR(30)\n);\n\nCREATE TABLE book (\n  book_id   INT PRIMARY KEY,\n  title     VARCHAR(60),\n  author_id INT REFERENCES author (author_id)\n);\n\nINSERT INTO author VALUES\n  (1, 'Chinua Achebe', 'Nigeria'),\n  (2, 'Zadie Smith', 'UK'),\n  (3, 'Ben Okri', 'Nigeria');\nINSERT INTO book VALUES\n  (1, 'Things Fall Apart', 1),\n  (2, 'White Teeth', 2),\n  (3, 'The Famished Road', 3),\n  (4, 'Arrow of God', 1),\n  (5, 'Swing Time', 2);",
  sol: "SELECT b.title, a.name\nFROM book b\nJOIN author a ON b.author_id = a.author_id\nWHERE a.country = 'Nigeria'\nORDER BY b.title;",
  checks: [["@result", "Arrow of God, Chinua Achebe; The Famished Road, Ben Okri; Things Fall Apart, Chinua Achebe"]],
  write: { task: "Join `book` and `author` on `author_id`. Return two columns, the book's `title` and its author's `name`, for authors whose `country` is `Nigeria`, sorted by title.", starter: "SELECT b.title, a.name\n" },
  fill: { code: "SELECT b.title, a.name\nFROM book b\nJOIN author a ON ___\n___ a.country = 'Nigeria'\nORDER BY b.title;", blanks: [["b.author_id = a.author_id", "a.author_id = b.author_id"], ["WHERE"]] },
  predict: { code: "SELECT a.name, COUNT(*)\nFROM author a\nJOIN book b ON b.author_id = a.author_id\nGROUP BY a.name\nORDER BY a.name;" },
  explain: "The `ON` part says which rows belong together: a book and the author with the same `author_id`. After the join, each row has columns from both tables, so `WHERE` can filter on the author's country." },

w3view: { title: "London staff view",
  setup: "CREATE TABLE staff (\n  staff_id INT PRIMARY KEY,\n  name     VARCHAR(30),\n  office   VARCHAR(20),\n  salary   INT\n);\n\nINSERT INTO staff VALUES\n  (1, 'Priya', 'London', 41000),\n  (2, 'Tom', 'Leeds', 35000),\n  (3, 'Ines', 'London', 52000),\n  (4, 'Kwame', 'Cardiff', 38000),\n  (5, 'Lena', 'London', 30000);",
  sol: "CREATE VIEW london_staff AS\nSELECT name, salary\nFROM staff\nWHERE office = 'London';\n\nSELECT name, salary\nFROM london_staff\nWHERE salary > 35000\nORDER BY name;",
  checks: [
    ["@result", "Ines, 52000; Priya, 41000"],
    ["SELECT table_name FROM information_schema.views WHERE table_schema = 'public'", "london_staff"],
    ["SELECT column_name FROM information_schema.columns WHERE table_name = 'london_staff' ORDER BY ordinal_position", "name; salary"]],
  write: { task: "Create a view `london_staff` with two columns, `name` and `salary`, for everyone whose `office` is `London`. Then query the view for the `name` and `salary` of London staff earning more than 35000, sorted by name.", starter: "CREATE VIEW london_staff AS\n" },
  fill: { code: "CREATE ___ london_staff AS\nSELECT name, salary\nFROM staff\nWHERE office = 'London';\n\nSELECT name, salary\nFROM ___\nWHERE salary > 35000\nORDER BY name;", blanks: [["VIEW"], ["london_staff"]] },
  predict: { code: "CREATE VIEW london_staff AS\nSELECT name, salary\nFROM staff\nWHERE office = 'London';\n\nSELECT ROUND(AVG(salary))\nFROM london_staff;" },
  explain: "Once a view exists you can use it in `FROM` like a table, and add your own `WHERE` and `ORDER BY`. The view's query runs first, so only London staff are ever seen through it." },

w3prepare: { title: "trains to a destination",
  setup: "CREATE TABLE train (\n  train_id    INT PRIMARY KEY,\n  destination VARCHAR(30),\n  platform    INT\n);\n\nINSERT INTO train VALUES\n  (1, 'Leeds', 4),\n  (2, 'Bristol', 2),\n  (3, 'Leeds', 7),\n  (4, 'Oxford', 1),\n  (5, 'Leeds', 2);",
  sol: "PREPARE trains_to (text) AS\nSELECT train_id, platform\nFROM train\nWHERE destination = $1\nORDER BY train_id;\n\nEXECUTE trains_to('Leeds');",
  checks: [
    ["@result", "1, 4; 3, 7; 5, 2"],
    ["SELECT name FROM pg_prepared_statements WHERE from_sql", "trains_to"]],
  write: { task: "Write a prepared statement `trains_to` that takes one `text` parameter and returns `train_id` and `platform` of the trains whose `destination` is `$1`, sorted by `train_id`. Then execute it with `'Leeds'`.", starter: "PREPARE trains_to (text) AS\n" },
  fill: { code: "PREPARE trains_to (___) AS\nSELECT train_id, platform\nFROM train\nWHERE destination = $1\nORDER BY train_id;\n\n___ trains_to('Leeds');", blanks: [["text", "varchar"], ["EXECUTE"]] },
  predict: { code: "PREPARE on_platform (int) AS\nSELECT destination\nFROM train\nWHERE platform = $1\nORDER BY train_id;\n\nEXECUTE on_platform(2);" },
  explain: "The type in brackets after the name says what kind of value `$1` will be, here `text`. `EXECUTE trains_to('Leeds')` puts `'Leeds'` where `$1` is and runs the query." },

w3dropTruncate: { title: "sensor clean-up",
  setup: "CREATE TABLE sensor (\n  sensor_id INT PRIMARY KEY,\n  room      VARCHAR(20)\n);\n\nCREATE TABLE reading (\n  reading_id INT PRIMARY KEY,\n  sensor_id  INT,\n  value      INT\n);\n\nCREATE TABLE import_tmp (\n  line TEXT\n);\n\nINSERT INTO sensor VALUES (1, 'Lab'), (2, 'Office');\nINSERT INTO reading VALUES (1, 1, 19), (2, 1, 22), (3, 2, 25), (4, 2, 18);\nINSERT INTO import_tmp VALUES ('1,19'), ('1,22');",
  sol: "DROP TABLE import_tmp;\nTRUNCATE TABLE reading;",
  checks: [
    ["SELECT table_name\nFROM information_schema.tables\nWHERE table_schema = 'public'\nORDER BY table_name", "reading; sensor"],
    ["SELECT COUNT(*) FROM reading", "0"],
    ["SELECT COUNT(*) FROM sensor", "2"]],
  write: { task: "The table `import_tmp` is no longer needed: remove it completely. Then remove every row from `reading` but keep the table. Leave `sensor` alone.", starter: "" },
  fill: { code: "___ import_tmp;\n___ reading;", blanks: [["DROP TABLE"], ["TRUNCATE TABLE", "TRUNCATE"]] },
  predict: { code: "DELETE FROM reading\nWHERE value > 20;\n\nSELECT COUNT(*) FROM reading;",
    ask: "This uses `DELETE` with a `WHERE`, not `TRUNCATE`. How many readings are left?" },
  explain: "`DROP TABLE` deletes the table and everything in it. `TRUNCATE TABLE` empties a table in one go but keeps its columns. `DELETE ... WHERE` removes only the rows that match." },

w3doBlock: { title: "mark inactive members",
  setup: "CREATE TABLE gym_member (\n  member_id INT PRIMARY KEY,\n  name      VARCHAR(30),\n  visits    INT,\n  status    VARCHAR(10)\n);\n\nINSERT INTO gym_member VALUES\n  (1, 'Nia', 12, NULL),\n  (2, 'Raf', 0, NULL),\n  (3, 'Elle', 4, NULL),\n  (4, 'Gus', 0, NULL);",
  sol: "DO $$\nDECLARE\n  m RECORD;\nBEGIN\n  FOR m IN SELECT member_id, visits FROM gym_member LOOP\n    IF m.visits = 0 THEN\n      UPDATE gym_member SET status = 'inactive' WHERE member_id = m.member_id;\n    ELSE\n      UPDATE gym_member SET status = 'active' WHERE member_id = m.member_id;\n    END IF;\n  END LOOP;\nEND $$;",
  checks: [["SELECT member_id, status\nFROM gym_member\nORDER BY member_id", "1, active; 2, inactive; 3, active; 4, inactive"]],
  write: { task: "Write a `DO` block that declares a `RECORD` variable and uses a `FOR` loop over the rows of `gym_member`. Use `IF ... ELSE` to set `status` to `'inactive'` when `visits` is 0 and to `'active'` otherwise.", starter: "DO $$\nDECLARE\n" },
  fill: { code: "DO $$\nDECLARE\n  m ___;\nBEGIN\n  FOR m IN SELECT member_id, visits FROM gym_member LOOP\n    IF m.visits = 0 THEN\n      UPDATE gym_member SET status = 'inactive' WHERE member_id = m.member_id;\n    ___\n      UPDATE gym_member SET status = 'active' WHERE member_id = m.member_id;\n    END IF;\n  END LOOP;\nEND $$;", blanks: [["RECORD"], ["ELSE"]] },
  predict: { code: "DO $$\nDECLARE\n  m RECORD;\nBEGIN\n  FOR m IN SELECT member_id, visits FROM gym_member LOOP\n    IF m.visits > 5 THEN\n      UPDATE gym_member SET status = 'gold' WHERE member_id = m.member_id;\n    ELSE\n      UPDATE gym_member SET status = 'standard' WHERE member_id = m.member_id;\n    END IF;\n  END LOOP;\nEND $$;\n\nSELECT COUNT(*) FROM gym_member WHERE status = 'standard';" },
  explain: "`m RECORD` declares a variable that holds one whole row, and the `FOR` loop fills it with each row in turn. `IF ... THEN ... ELSE ... END IF` picks one of two updates for that row, so every member ends up with a status." },

// ---------------- Week 4 ----------------
w4innerJoin: { title: "pets and their owners",
  setup: "CREATE TABLE owner (\n  owner_id   INT PRIMARY KEY,\n  owner_name VARCHAR(30) NOT NULL\n);\n\nCREATE TABLE pet (\n  pet_id   INT PRIMARY KEY,\n  pet_name VARCHAR(30) NOT NULL,\n  owner_id INT REFERENCES owner (owner_id)\n);\n\nINSERT INTO owner VALUES\n  (1, 'Ana'), (2, 'Ben'), (3, 'Cleo');\n\nINSERT INTO pet VALUES\n  (1, 'Biscuit', 2), (2, 'Pip', 1), (3, 'Rex', NULL), (4, 'Mochi', 2), (5, 'Nala', 1), (6, 'Ziggy', NULL);",
  sol: "SELECT p.pet_name, o.owner_name\nFROM pet p\nINNER JOIN owner o ON p.owner_id = o.owner_id\nORDER BY p.pet_name;",
  checks: [["@result", "Biscuit, Ben; Mochi, Ben; Nala, Ana; Pip, Ana"]],
  write: { task: "Use an `INNER JOIN` to return two columns, `pet_name` then the owner's `owner_name`, for pets that have an owner. Sort by `pet_name`. The first row is `Biscuit, Ben`.", starter: "SELECT\n" },
  fill: { code: "SELECT p.pet_name, o.owner_name\nFROM pet p\n___ owner o ___ p.owner_id = o.owner_id\nORDER BY p.pet_name;", blanks: [["INNER JOIN", "JOIN"], ["ON"]] },
  predict: { code: "SELECT COUNT(*)\nFROM pet NATURAL JOIN owner;",
    ask: "`NATURAL JOIN` joins on the columns that have the same name in both tables. What does this return?" },
  explain: "The `ON` condition says which rows belong together: a pet and the owner with the same `owner_id`. An `INNER JOIN` drops Rex and Ziggy (no owner) and Cleo (no pets), because none of them has a partner." },

w4leftJoin: { title: "cities and airports",
  setup: "CREATE TABLE city (\n  city_id   INT PRIMARY KEY,\n  city_name VARCHAR(30) NOT NULL\n);\n\nCREATE TABLE airport (\n  code    CHAR(3) PRIMARY KEY,\n  city_id INT REFERENCES city (city_id)\n);\n\nINSERT INTO city VALUES\n  (1, 'Bath'), (2, 'Belfast'), (3, 'Leeds'), (4, 'York');\n\nINSERT INTO airport VALUES\n  ('BFS', 2), ('BHD', 2), ('LBA', 3);",
  sol: "SELECT c.city_name, a.code\nFROM city c\nLEFT JOIN airport a ON a.city_id = c.city_id\nORDER BY c.city_name, a.code;",
  checks: [["@result", "Bath, null; Belfast, BFS; Belfast, BHD; Leeds, LBA; York, null"]],
  write: { task: "Return two columns, every city's `city_name` then the `code` of its airport, sorted by `city_name` and then by `code`. Cities without an airport must still appear, with `null` as the code, for example `Bath, null`.", starter: "SELECT\n" },
  fill: { code: "SELECT c.city_name, a.code\nFROM city c\n___ airport a ON a.city_id = c.city_id\nORDER BY c.city_name, a.code;", blanks: [["LEFT JOIN", "LEFT OUTER JOIN"]] },
  predict: { code: "SELECT COUNT(*), COUNT(a.code)\nFROM city c\nLEFT JOIN airport a ON a.city_id = c.city_id;",
    ask: "What does it return? Give both numbers, like `7, 5`." },
  explain: "A `LEFT JOIN` keeps every city, even one with no airport, and puts NULL in the airport columns. Belfast has two airports, so it appears twice. `COUNT(a.code)` skips the NULL rows; `COUNT(*)` does not." },

w4noMatch: { title: "rooms nobody booked",
  setup: "CREATE TABLE room (\n  room_no INT PRIMARY KEY,\n  floor   INT NOT NULL\n);\n\nCREATE TABLE booking (\n  booking_id INT PRIMARY KEY,\n  room_no    INT REFERENCES room (room_no),\n  guest      VARCHAR(30)\n);\n\nINSERT INTO room VALUES\n  (11, 1), (12, 1), (21, 2), (22, 2), (31, 3);\n\nINSERT INTO booking VALUES\n  (1, 12, 'Hope'), (2, 21, 'Ivan'), (3, 12, 'Jade');",
  sol: "SELECT r.room_no\nFROM room r\nLEFT JOIN booking b ON b.room_no = r.room_no\nWHERE b.booking_id IS NULL\nORDER BY r.room_no;",
  checks: [["@result", "11; 22; 31"]],
  write: { task: "Return the `room_no` of every room that has no booking, sorted by `room_no`. Use a `LEFT JOIN` from `room r` to `booking b`, then keep only the rooms that the join found no booking for.", starter: "SELECT r.room_no\nFROM room r\n" },
  fill: { code: "SELECT r.room_no\nFROM room r\n___ booking b ON b.room_no = r.room_no\nWHERE b.booking_id ___\nORDER BY r.room_no;", blanks: [["LEFT JOIN", "LEFT OUTER JOIN"], ["IS NULL"]] },
  predict: { code: "SELECT COUNT(*)\nFROM room r\nLEFT JOIN booking b ON b.room_no = r.room_no\nWHERE b.booking_id IS NOT NULL;" },
  explain: "The `LEFT JOIN` keeps every room. Rooms with no booking get NULL in the `booking` columns, and `IS NULL` picks out just those. `IS NOT NULL` does the opposite and keeps the rows that did match." },

w4fullJoin: { title: "tutors and lessons",
  setup: "CREATE TABLE tutor (\n  tutor_id   INT PRIMARY KEY,\n  tutor_name VARCHAR(30) NOT NULL\n);\n\nCREATE TABLE lesson (\n  lesson_id INT PRIMARY KEY,\n  subject   VARCHAR(30) NOT NULL,\n  tutor_id  INT REFERENCES tutor (tutor_id)\n);\n\nINSERT INTO tutor VALUES\n  (1, 'Mia'), (2, 'Noah'), (3, 'Ola');\n\nINSERT INTO lesson VALUES\n  (1, 'Maths', 1), (2, 'Art', NULL), (3, 'French', 1);",
  sol: "SELECT t.tutor_name, l.subject\nFROM tutor t\nFULL OUTER JOIN lesson l ON l.tutor_id = t.tutor_id;",
  checks: [["@result", "Mia, Maths; Mia, French; Noah, null; Ola, null; null, Art"]],
  write: { task: "Return two columns, `tutor_name` then the lesson's `subject`, for every tutor AND every lesson. A tutor with no lesson gets `null` as the subject (`Noah, null`); a lesson with no tutor gets `null` as the name (`null, Art`). Any row order.", starter: "SELECT t.tutor_name, l.subject\nFROM tutor t\n" },
  fill: { code: "SELECT t.tutor_name, l.subject\nFROM tutor t\n___ lesson l ON l.tutor_id = t.tutor_id;", blanks: [["FULL OUTER JOIN", "FULL JOIN"]] },
  predict: { code: "SELECT COUNT(*)\nFROM lesson l\nRIGHT JOIN tutor t ON l.tutor_id = t.tutor_id;" },
  explain: "A `FULL OUTER JOIN` is a left and a right join together: nothing from either table is lost, and the missing side is NULL. A `RIGHT JOIN` keeps every row of the table after `JOIN` (here `tutor`), so Mia counts twice and Noah and Ola once each." },

w4threeJoin: { title: "items, aisles and stores",
  setup: "CREATE TABLE store (\n  store_id INT PRIMARY KEY,\n  town     VARCHAR(30) NOT NULL\n);\n\nCREATE TABLE aisle (\n  aisle_id INT PRIMARY KEY,\n  aisle_no INT NOT NULL,\n  store_id INT REFERENCES store (store_id)\n);\n\nCREATE TABLE item (\n  item_id   INT PRIMARY KEY,\n  item_name VARCHAR(30) NOT NULL,\n  aisle_id  INT REFERENCES aisle (aisle_id)\n);\n\nINSERT INTO store VALUES\n  (1, 'Hull'), (2, 'Ripon');\n\nINSERT INTO aisle VALUES\n  (1, 4, 1), (2, 7, 2), (3, 2, 2);\n\nINSERT INTO item VALUES\n  (1, 'Bread', 1), (2, 'Milk', 3), (3, 'Rice', 2), (4, 'Soap', NULL);",
  sol: "SELECT i.item_name, s.town\nFROM item i\nJOIN aisle a ON a.aisle_id = i.aisle_id\nJOIN store s ON s.store_id = a.store_id\nORDER BY i.item_name;",
  checks: [["@result", "Bread, Hull; Milk, Ripon; Rice, Ripon"]],
  write: { task: "Each item is in an aisle, and each aisle is in a store. Return two columns, `item_name` then the `town` of the item's store, for items that have an aisle. Sort by `item_name`. The first row is `Bread, Hull`.", starter: "SELECT i.item_name, s.town\nFROM item i\n" },
  fill: { code: "SELECT i.item_name, s.town\nFROM item i\nJOIN aisle a ON a.aisle_id = i.aisle_id\n___ store s ON ___\nORDER BY i.item_name;", blanks: [["JOIN", "INNER JOIN"], ["s.store_id = a.store_id", "a.store_id = s.store_id"]] },
  predict: { code: "SELECT s.town, COUNT(*)\nFROM item i\nJOIN aisle a ON a.aisle_id = i.aisle_id\nJOIN store s ON s.store_id = a.store_id\nGROUP BY s.town\nORDER BY s.town;",
    ask: "What does it return? Write each row as `town, count`, with rows separated by semicolons." },
  explain: "There is no direct link from `item` to `store`, so you go through `aisle`: the first `JOIN` finds each item's aisle and the second finds that aisle's store. Soap has no aisle, so the inner joins drop it." },

w4entity: { title: "a flight entity",
  sol: "@Entity\n@Table(name = \"flights\")\npublic class Flight {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String code;\n  private int seats;\n}",
  checks: [
    ["tables:", "flights"],
    ["sql: SELECT column_name FROM information_schema.columns WHERE table_name = 'flights' ORDER BY column_name", "code; id; seats"],
    ["sql: SELECT is_identity FROM information_schema.columns WHERE table_name = 'flights' AND column_name = 'id'", "YES"]],
  write: { task: "Write an entity class `Flight` stored in a table called `flights`. Give it three fields: `Long id`, the primary key, created by the database with the `IDENTITY` strategy; `String code`; and `int seats`.", starter: "@Entity\n" },
  fill: { code: "@___\n@Table(name = \"flights\")\npublic class Flight {\n  @___\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String code;\n  private int seats;\n}", blanks: [["Entity"], ["Id"]] },
  predict: { code: "@Entity\npublic class BoardingPass {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String seat;\n}", expr: "tables:",
    ask: "This class has no `@Table`. What is the table called? (Spring Boot naming)" },
  explain: "`@Entity` turns the class into a table and `@Table(name = \"flights\")` chooses the name. `@Id` is the primary key; `@GeneratedValue(strategy = GenerationType.IDENTITY)` means the database fills it in. Without `@Table`, `BoardingPass` becomes `boarding_pass`." },

w4column: { title: "product column rules",
  sol: "@Entity\npublic class Product {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  @Column(nullable = false, unique = true)\n  private String sku;\n\n  @Column(name = \"product_name\")\n  private String name;\n\n  private Integer stockLevel;\n}",
  checks: [
    ["sql: SELECT column_name, is_nullable FROM information_schema.columns WHERE table_name = 'product' ORDER BY column_name", "id, NO; product_name, YES; sku, NO; stock_level, YES"],
    ["sql: SELECT k.column_name FROM information_schema.table_constraints c JOIN information_schema.key_column_usage k ON k.constraint_name = c.constraint_name WHERE c.table_name = 'product' AND c.constraint_type = 'UNIQUE'", "sku"]],
  write: { task: "Write an entity `Product` (table name left as the default) with four fields: `Long id`, the primary key, generated with `IDENTITY`; `String sku`, which must never be NULL and must never repeat; `String name`, stored in a column called `product_name`; and `Integer stockLevel`, with no annotation.", starter: "@Entity\npublic class Product {\n" },
  fill: { code: "@Entity\npublic class Product {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  @Column(nullable = false, ___ = true)\n  private String sku;\n\n  @___(name = \"product_name\")\n  private String name;\n\n  private Integer stockLevel;\n}", blanks: [["unique"], ["Column"]] },
  predict: { code: "@Entity\npublic class Ticket {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  @Column(nullable = false)\n  private String seat;\n}", expr: "sql: SELECT is_nullable FROM information_schema.columns WHERE table_name = 'ticket' AND column_name = 'seat'",
    ask: "May the `seat` column hold NULL? Answer `YES` or `NO`." },
  explain: "`nullable = false` adds `NOT NULL` and `unique = true` adds a `UNIQUE` rule, just as you would write in `CREATE TABLE`. `name = \"product_name\"` overrides the column name; a field with no `@Column`, like `stockLevel`, gets the Spring Boot name `stock_level`." },

w4transient: { title: "a parcel's label",
  sol: "@Entity\npublic class Parcel {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String trackingCode;\n  private int weightGrams;\n\n  @Transient\n  private String label;\n}",
  checks: [
    ["tables:", "parcel"],
    ["sql: SELECT column_name FROM information_schema.columns WHERE table_name = 'parcel' ORDER BY column_name", "id; tracking_code; weight_grams"]],
  write: { task: "Write an entity `Parcel` with four fields: `Long id`, the primary key, generated with `IDENTITY`; `String trackingCode`; `int weightGrams`; and `String label`, which is built in code for printing and must not be stored in the table.", starter: "@Entity\npublic class Parcel {\n" },
  fill: { code: "@Entity\npublic class Parcel {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String trackingCode;\n  private int weightGrams;\n\n  @___\n  private String label;\n}", blanks: [["Transient"]] },
  predict: { code: "@Entity\npublic class Sensor {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String place;\n\n  @Transient\n  private double lastReading;\n}", expr: "sql: SELECT CASE WHEN COUNT(*) > 0 THEN 'YES' ELSE 'NO' END FROM information_schema.columns WHERE table_name = 'sensor' AND column_name = 'last_reading'",
    ask: "Does the `sensor` table have a `last_reading` column? Answer `YES` or `NO`." },
  explain: "`@Transient` means: keep this field in Java, but do not map it to a column. Hibernate makes columns for `id`, `trackingCode` and `weightGrams` only, so `label` is never saved, and a parcel loaded from the database has `null` there." },

w4manyToOne: { title: "players in a team",
  sol: "@Entity\npublic class Team {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  @Column(name = \"team_id\")\n  private Long id;\n\n  private String name;\n\n  @OneToMany(mappedBy = \"team\")\n  private List<Player> players = new ArrayList<>();\n}\n\n@Entity\npublic class Player {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  @Column(name = \"player_id\")\n  private Long id;\n\n  private String name;\n\n  @ManyToOne\n  @JoinColumn(name = \"team_id\")\n  private Team team;\n}",
  checks: [
    ["tables:", "player, team"],
    ["sql: SELECT column_name FROM information_schema.columns WHERE table_name = 'team' ORDER BY column_name", "name; team_id"],
    ["sql: SELECT column_name FROM information_schema.columns WHERE table_name = 'player' ORDER BY column_name", "name; player_id; team_id"],
    ["jpql: SELECT COUNT(p) FROM Player p WHERE p.team.name = 'Kites'", "0"],
    ["jpql: SELECT COUNT(p) FROM Team t JOIN t.players p", "0"]],
  write: { task: "Write entities `Team` and `Player`. Each has `Long id`, generated with `IDENTITY` and stored in a column `team_id` (for `Team`) or `player_id` (for `Player`), and a `String name`. Many players belong to one team: give `Player` a field `Team team` with the foreign key column `team_id`. Give `Team` a field `List<Player> players` for the other side of the same link, so no extra table is made.", starter: "@Entity\npublic class Team {\n" },
  fill: { code: "@Entity\npublic class Team {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  @Column(name = \"team_id\")\n  private Long id;\n\n  private String name;\n\n  @___(mappedBy = \"team\")\n  private List<Player> players = new ArrayList<>();\n}\n\n@Entity\npublic class Player {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  @Column(name = \"player_id\")\n  private Long id;\n\n  private String name;\n\n  @___\n  @JoinColumn(name = \"team_id\")\n  private Team team;\n}", blanks: [["OneToMany"], ["ManyToOne"]] },
  predict: { code: "@Entity\npublic class Kennel {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String town;\n}\n\n@Entity\npublic class Dog {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String name;\n\n  @ManyToOne\n  private Kennel kennel;\n}", expr: "sql: SELECT column_name FROM information_schema.columns WHERE table_name = 'dog' AND column_name NOT IN ('id', 'name')",
    ask: "There is no `@JoinColumn`. What is the foreign key column in `dog` called? (Spring Boot naming)" },
  explain: "The many side (`Player`) holds the foreign key, so it gets `@ManyToOne` and `@JoinColumn`. The one side (`Team`) gets `@OneToMany(mappedBy = \"team\")`, which points at the `team` field instead of storing the link a second time." },

w4manyToMany: { title: "films and actors",
  sol: "@Entity\npublic class Actor {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String name;\n}\n\n@Entity\npublic class Film {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String title;\n\n  @ManyToMany\n  @JoinTable(name = \"film_actor\",\n    joinColumns = @JoinColumn(name = \"film_id\"),\n    inverseJoinColumns = @JoinColumn(name = \"actor_id\"))\n  private Set<Actor> actors = new HashSet<>();\n}",
  checks: [
    ["tables:", "actor, film, film_actor"],
    ["sql: SELECT column_name FROM information_schema.columns WHERE table_name = 'film_actor' ORDER BY column_name", "actor_id; film_id"],
    ["jpql: SELECT COUNT(a) FROM Film f JOIN f.actors a", "0"]],
  write: { task: "Write entities `Actor` (`Long id`, `String name`) and `Film` (`Long id`, `String title`), both ids generated with `IDENTITY`. A film has many actors and an actor is in many films: give `Film` a field `Set<Actor> actors`, stored in a join table `film_actor` with the columns `film_id` and `actor_id`.", starter: "@Entity\npublic class Actor {\n" },
  fill: { code: "@Entity\npublic class Actor {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String name;\n}\n\n@Entity\npublic class Film {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String title;\n\n  @ManyToMany\n  @___(name = \"film_actor\",\n    ___ = @JoinColumn(name = \"film_id\"),\n    inverseJoinColumns = @JoinColumn(name = \"actor_id\"))\n  private Set<Actor> actors = new HashSet<>();\n}", blanks: [["JoinTable"], ["joinColumns"]] },
  predict: { code: "@Entity\npublic class Post {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String heading;\n\n  @ManyToMany\n  @JoinTable(name = \"post_tag\",\n    joinColumns = @JoinColumn(name = \"post_id\"),\n    inverseJoinColumns = @JoinColumn(name = \"tag_id\"))\n  private Set<Tag> tags = new HashSet<>();\n}\n\n@Entity\npublic class Tag {\n  @Id\n  @GeneratedValue(strategy = GenerationType.IDENTITY)\n  private Long id;\n\n  private String label;\n}", expr: "sql: SELECT COUNT(*) FROM information_schema.columns WHERE table_name = 'post_tag'",
    ask: "How many columns does the join table `post_tag` have?" },
  explain: "`@ManyToMany` with `@JoinTable` makes a third table that only holds pairs of keys. `joinColumns` is the key for the entity you are in (`film_id`), and `inverseJoinColumns` is the key for the other entity (`actor_id`)." },

w4jpqlPath: { title: "flights by Irish airlines",
  entities: "@Entity\npublic class Airline {\n  @Id\n  private Long id;\n  private String name;\n  private String country;\n}\n\n@Entity\npublic class Flight {\n  @Id\n  private Long id;\n  private String flightCode;\n  private int seats;\n\n  @ManyToOne\n  private Airline airline;\n}",
  setup: "INSERT INTO airline (id, name, country) VALUES (1, 'Shamrock Air', 'Ireland'), (2, 'Thistle Jet', 'Scotland'), (3, 'Liffey Wings', 'Ireland');\nINSERT INTO flight (id, flight_code, seats, airline_id) VALUES (1, 'SA12', 180, 1), (2, 'TJ40', 90, 2), (3, 'LW07', 70, 3), (4, 'SA03', 150, 1), (5, 'TJ88', 120, 2);",
  sol: "SELECT f.flightCode FROM Flight f WHERE f.airline.country = 'Ireland' ORDER BY f.flightCode",
  checks: [["@result", "LW07; SA03; SA12"]],
  write: { task: "Write a JPQL query for the `flightCode` of every flight whose airline's country is `Ireland`, sorted by `flightCode`. Use entity and field names, not table and column names, and reach the country by following the `airline` field, without writing a `JOIN`. The first row is `LW07`.", starter: "SELECT " },
  fill: { code: "SELECT f.flightCode FROM ___ f WHERE f.___ = 'Ireland' ORDER BY f.flightCode", blanks: [["Flight"], ["airline.country"]] },
  predict: { code: "SELECT COUNT(f) FROM Flight f WHERE f.airline.name = 'Thistle Jet'" },
  explain: "In JPQL you write the class name `Flight` and the field `flightCode`, even though the table column is `flight_code`. The dots in `f.airline.country` walk along the `@ManyToOne` link, so you do not need a `JOIN ... ON`." },

w4jpqlGroup: { title: "sales per shop",
  entities: "@Entity\npublic class Shop {\n  @Id\n  private Long id;\n  private String name;\n}\n\n@Entity\npublic class Sale {\n  @Id\n  private Long id;\n  private int amount;\n\n  @ManyToOne\n  private Shop shop;\n}",
  setup: "INSERT INTO shop (id, name) VALUES (1, 'Corner'), (2, 'Market'), (3, 'Station');\nINSERT INTO sale (id, amount, shop_id) VALUES (1, 5, 2), (2, 12, 1), (3, 7, 2), (4, 3, 3), (5, 9, 2), (6, 4, 1);",
  sol: "SELECT sh.name, COUNT(s) FROM Sale s JOIN s.shop sh GROUP BY sh.name ORDER BY sh.name",
  checks: [["@result", "Corner, 2; Market, 3; Station, 1"]],
  write: { task: "Write a JPQL query over `Sale s` that joins each sale to its shop `sh` through the `shop` field and returns two columns: the shop's `name` and how many sales it has. Group by the shop name and sort by name. The first row is `Corner, 2`.", starter: "SELECT " },
  fill: { code: "SELECT sh.name, ___ FROM Sale s JOIN s.shop sh ___ sh.name ORDER BY sh.name", blanks: [["COUNT(s)", "COUNT(*)"], ["GROUP BY"]] },
  predict: { code: "SELECT SUM(s.amount) FROM Sale s JOIN s.shop sh WHERE sh.name = 'Market'" },
  explain: "`JOIN s.shop sh` follows the `shop` field of each sale, so `sh` stands for that sale's shop. `GROUP BY sh.name` makes one group per shop, and `COUNT(s)` counts the sales in each group." },

// ---------------- Week 5 ----------------
w5createGraph: { title: "instructors and classes",
  setup: "",
  sol: "CREATE (mia:Instructor {name: 'Mia'}),\n       (raj:Instructor {name: 'Raj'}),\n       (mia)-[:TEACHES]->(:GymClass {name: 'Spin', day: 'Monday'}),\n       (mia)-[:TEACHES]->(:GymClass {name: 'Pilates', day: 'Thursday'}),\n       (raj)-[:TEACHES]->(:GymClass {name: 'Boxing', day: 'Tuesday'})",
  checks: [
    ["MATCH (i:Instructor)-[:TEACHES]->(c:GymClass) RETURN i.name, c.name, c.day ORDER BY c.name", "Raj, Boxing, Tuesday; Mia, Pilates, Thursday; Mia, Spin, Monday"],
    ["MATCH (i:Instructor) RETURN count(i)", "2"],
    ["MATCH (n) RETURN count(n)", "5"]],
  write: { task: "The graph is empty. Turn this table (instructor, class, day) into a graph: `Mia, Spin, Monday`; `Mia, Pilates, Thursday`; `Raj, Boxing, Tuesday`. Make one `Instructor` node per instructor (property `name`), one `GymClass` node per class (properties `name` and `day`), and a `TEACHES` relationship from each instructor to each of their classes. Mia must be one node, not two.", starter: "CREATE " },
  fill: { code: "___ (mia:Instructor {name: 'Mia'}),\n       (raj:Instructor {name: 'Raj'}),\n       (mia)-[:TEACHES]->(:GymClass {name: 'Spin', day: 'Monday'}),\n       (___)-[:TEACHES]->(:GymClass {name: 'Pilates', day: 'Thursday'}),\n       (raj)-[:TEACHES]->(:GymClass {name: 'Boxing', day: 'Tuesday'})", blanks: [["CREATE", "create"], ["mia"]] },
  predict: { code: "CREATE (:Town {name: 'Ely'});\nCREATE (:Town {name: 'Ely'})-[:NEAR]->(:Town {name: 'Diss'});\n\nMATCH (t:Town)\nRETURN count(t)",
    ask: "The graph starts empty. How many `Town` nodes does the last query count?" },
  explain: "Instructors and classes are the nouns, so they become nodes; `day` describes a class, so it is a property of `GymClass`; teaching links them, so it is a relationship. Reusing the variable `mia` points at the node already made instead of creating a second Mia." },

w5linkNodes: { title: "assigning a van",
  setup: "CREATE (:Driver {name: 'Omar'}),\n       (pia:Driver {name: 'Pia'}),\n       (:Van {reg: 'KX21'}),\n       (lm07:Van {reg: 'LM07'}),\n       (pia)-[:DRIVES {shift: 'late'}]->(lm07)",
  sol: "MATCH (p:Driver {name: 'Omar'}), (v:Van {reg: 'KX21'})\nCREATE (p)-[:DRIVES {shift: 'early'}]->(v)",
  checks: [
    ["MATCH (p:Driver)-[r:DRIVES]->(v:Van) RETURN p.name, v.reg, r.shift ORDER BY p.name", "Omar, KX21, early; Pia, LM07, late"],
    ["MATCH (n) RETURN count(n)", "4"]],
  write: { task: "The `Driver` named `'Omar'` and the `Van` with `reg` `'KX21'` already exist. Find both with one `MATCH`, then `CREATE` a `DRIVES` relationship from Omar to the van, with the property `shift` set to `'early'`. Do not make any new nodes.", starter: "MATCH " },
  fill: { code: "___ (p:Driver {name: 'Omar'}), (v:Van {reg: 'KX21'})\nCREATE (p)-[:DRIVES ___]->(v)", blanks: [["MATCH", "match"], ["{shift: 'early'}", "{shift:'early'}", "{shift: \"early\"}", "{shift:\"early\"}"]] },
  predict: { code: "MATCH (p:Driver {name: 'Pia'}), (v:Van)\nCREATE (p)-[:DRIVES]->(v);\n\nMATCH (:Driver {name: 'Pia'})-[r:DRIVES]->(:Van)\nRETURN count(r)",
    ask: "Pia already drives one van. How many `DRIVES` relationships from Pia does the last query count?" },
  explain: "`MATCH` finds the driver and the van that already exist and names them `p` and `v`, so `CREATE` only adds the relationship between them. A relationship's properties go inside its square brackets, as in `[:DRIVES {shift: 'early'}]`. `CREATE` never checks for an existing relationship, so it can add a second one between the same nodes." },

w5match: { title: "flights from an airport",
  setup: "CREATE (bhx:Airport {code: 'BHX'}),\n       (man:Airport {code: 'MAN'}),\n       (:Flight {number: 'QX12'})-[:DEPARTS_FROM]->(bhx),\n       (:Flight {number: 'AB40'})-[:DEPARTS_FROM]->(bhx),\n       (:Flight {number: 'QX90'})-[:DEPARTS_FROM]->(man)",
  sol: "MATCH (a:Airport {code: 'BHX'})<-[:DEPARTS_FROM]-(f:Flight)\nRETURN f.number AS flight\nORDER BY flight",
  checks: [["@result", "AB40; QX12"]],
  write: { task: "Start your pattern at the `Airport` node with `code` `'BHX'`. The `DEPARTS_FROM` arrows point from `Flight` to `Airport`, so follow them backwards. Return one column, each flight's `number` renamed with `AS flight`, sorted by number. The first row is `AB40`.", starter: "MATCH (a:Airport {code: 'BHX'})" },
  fill: { code: "MATCH (a:Airport {code: 'BHX'})___[:DEPARTS_FROM]-(f:Flight)\nRETURN f.number ___ flight\nORDER BY flight", blanks: [["<-"], ["AS", "as"]] },
  predict: { code: "MATCH (a:Airport {code: 'BHX'})-[:DEPARTS_FROM]-(f:Flight)\nRETURN count(f)",
    ask: "This pattern has no arrow head at either end. What does it return?" },
  explain: "The relationship was created from flight to airport, so starting at the airport you need `<-[:DEPARTS_FROM]-`. Leaving out the arrow head (`-[:DEPARTS_FROM]-`) matches the relationship in either direction. `AS flight` names the output column." },

w5where: { title: "experienced hikers",
  setup: "CREATE (:Hiker {name: 'Nell', age: 41, level: 'expert'}),\n       (:Hiker {name: 'Otto', age: 35}),\n       (:Hiker {name: 'Pia', age: 27, level: 'beginner'}),\n       (:Hiker {name: 'Rex', age: 52, level: 'improver'}),\n       (:Hiker {name: 'Sue', age: 19})",
  sol: "MATCH (h:Hiker)\nWHERE h.age > 30 AND h.level IS NOT NULL\nRETURN h.name, h.level\nORDER BY h.name",
  checks: [["@result", "Nell, expert; Rex, improver"]],
  write: { task: "Return two columns, `name` then `level`, for every `Hiker` older than 30 who has a `level` property. Sort by `name`. The first row is `Nell, expert`.", starter: "MATCH (h:Hiker)\n" },
  fill: { code: "MATCH (h:Hiker)\nWHERE h.age > 30 ___ h.level ___\nRETURN h.name, h.level\nORDER BY h.name", blanks: [["AND", "and"], ["IS NOT NULL", "is not null"]] },
  predict: { code: "MATCH (h:Hiker)\nWHERE h.level = null\nRETURN h.name",
    ask: "What does it return? Write `(no rows)` if nothing comes back." },
  explain: "A hiker with no `level` property gives null for `h.level`. Any comparison with null, even `= null`, is null rather than true, so `WHERE` drops the row. Use `IS NULL` or `IS NOT NULL` to test for a missing value." },

w5relProps: { title: "rides in May",
  setup: "CREATE (ida:Cyclist {name: 'Ida'}),\n       (joe:Cyclist {name: 'Joe'}),\n       (coast:Route {name: 'Coast'}),\n       (hills:Route {name: 'Hills'}),\n       (ida)-[:RODE {km: 42, month: 'May'}]->(coast),\n       (ida)-[:RODE {km: 18, month: 'June'}]->(hills),\n       (joe)-[:RODE {km: 35, month: 'May'}]->(hills),\n       (joe)-[:RODE {km: 12, month: 'June'}]->(coast)",
  sol: "MATCH (c:Cyclist)-[r:RODE]->(t:Route)\nWHERE r.month = 'May'\nRETURN c.name, t.name, r.km\nORDER BY r.km",
  checks: [["@result", "Joe, Hills, 35; Ida, Coast, 42"]],
  write: { task: "Each `RODE` relationship from a `Cyclist` to a `Route` has the properties `km` and `month`. Return three columns, the cyclist's `name`, the route's `name`, then `km`, for every ride in `'May'`, sorted by `km` from lowest to highest. The first row is `Joe, Hills, 35`.", starter: "MATCH (c:Cyclist)" },
  fill: { code: "MATCH (c:Cyclist)-[r:RODE]->(t:Route)\nWHERE ___ = 'May'\nRETURN c.name, t.name, ___\nORDER BY r.km", blanks: [["r.month"], ["r.km"]] },
  predict: { code: "MATCH (:Cyclist {name: 'Joe'})-[r:RODE]->(:Route)\nRETURN sum(r.km)" },
  explain: "The `km` and `month` describe one ride, so they are stored on the `RODE` relationship, not on the cyclist or the route. Naming the relationship `r` lets you use `r.month` in `WHERE` and `r.km` in `RETURN` and `ORDER BY`." },

w5orderSkip: { title: "third and fourth best games",
  setup: "CREATE (:Game {title: 'Orbit', score: 81}),\n       (:Game {title: 'Tiny Farm', score: 93}),\n       (:Game {title: 'Dune Racer', score: 77}),\n       (:Game {title: 'Pixel Knights', score: 88}),\n       (:Game {title: 'Go', score: 85})",
  sol: "MATCH (g:Game)\nRETURN g.title, g.score\nORDER BY g.score DESC\nSKIP 2\nLIMIT 2",
  checks: [["@result", "Go, 85; Orbit, 81"]],
  write: { task: "Return two columns, `title` then `score`, for the `Game` nodes with the 3rd and 4th highest `score` only, highest first. Use `ORDER BY`, `SKIP` and `LIMIT`.", starter: "MATCH (g:Game)\n" },
  fill: { code: "MATCH (g:Game)\nRETURN g.title, g.score\nORDER BY g.score ___\nSKIP 2\n___ 2", blanks: [["DESC", "desc"], ["LIMIT", "limit"]] },
  predict: { code: "MATCH (g:Game)\nRETURN g.title\nORDER BY size(g.title) DESC\nLIMIT 1" },
  explain: "`ORDER BY g.score DESC` puts the highest score first. `SKIP 2` throws away the top two rows and `LIMIT 2` keeps the next two. You can also sort by an expression, such as `size(g.title)`, the length of the title." },

w5count: { title: "recipes per ingredient",
  setup: "CREATE (egg:Ingredient {name: 'Egg'}),\n       (flour:Ingredient {name: 'Flour'}),\n       (milk:Ingredient {name: 'Milk'}),\n       (pancake:Recipe {name: 'Pancakes', minutes: 20}),\n       (omelette:Recipe {name: 'Omelette', minutes: 10}),\n       (bread:Recipe {name: 'Bread', minutes: 90}),\n       (scone:Recipe {name: 'Scones', minutes: 25}),\n       (pancake)-[:USES]->(egg), (pancake)-[:USES]->(flour), (pancake)-[:USES]->(milk),\n       (omelette)-[:USES]->(egg), (omelette)-[:USES]->(milk),\n       (bread)-[:USES]->(flour),\n       (scone)-[:USES]->(flour), (scone)-[:USES]->(milk)",
  sol: "MATCH (r:Recipe)-[:USES]->(i:Ingredient)\nRETURN i.name, count(r) AS recipes\nORDER BY recipes DESC, i.name",
  checks: [["@result", "Flour, 3; Milk, 3; Egg, 2"]],
  write: { task: "For each `Ingredient`, return two columns: its `name`, then how many recipes have a `USES` relationship to it, as `recipes`. Sort by `recipes` from most to fewest, and ingredients with the same number by name. The first row is `Flour, 3`.", starter: "MATCH (r:Recipe)-[:USES]->(i:Ingredient)\n" },
  fill: { code: "MATCH (r:Recipe)-[:USES]->(i:Ingredient)\nRETURN i.name, ___(r) AS recipes\nORDER BY recipes ___, i.name", blanks: [["count", "COUNT"], ["DESC", "desc"]] },
  predict: { code: "MATCH (r:Recipe)-[:USES]->(i:Ingredient {name: 'Milk'})\nRETURN min(r.minutes)" },
  explain: "`i.name` is not an aggregate, so Cypher groups by it automatically and `count(r)` counts the recipes in each group. There is no `GROUP BY` to write. `min`, `max`, `sum` and `avg` group the same way." },

w5with: { title: "authors with popular posts",
  setup: "CREATE (ana:Author {name: 'Ana'}),\n       (ben:Author {name: 'Ben'}),\n       (cy:Author {name: 'Cy'}),\n       (ana)-[:WROTE]->(:Post {likes: 30}),\n       (ana)-[:WROTE]->(:Post {likes: 25}),\n       (ben)-[:WROTE]->(:Post {likes: 12}),\n       (ben)-[:WROTE]->(:Post {likes: 8}),\n       (cy)-[:WROTE]->(:Post {likes: 70})",
  sol: "MATCH (a:Author)-[:WROTE]->(p:Post)\nWITH a, sum(p.likes) AS likes\nWHERE likes >= 50\nRETURN a.name, likes\nORDER BY a.name",
  checks: [["@result", "Ana, 55; Cy, 70"]],
  write: { task: "Use `WITH` to add up the `likes` of each author's posts as `likes`, then keep only authors with 50 or more. Return two columns, the author's `name` then `likes`, sorted by `name`. The first row is `Ana, 55`.", starter: "MATCH (a:Author)-[:WROTE]->(p:Post)\n" },
  fill: { code: "MATCH (a:Author)-[:WROTE]->(p:Post)\n___ a, sum(p.likes) AS likes\n___ likes >= 50\nRETURN a.name, likes\nORDER BY a.name", blanks: [["WITH", "with"], ["WHERE", "where"]] },
  predict: { code: "MATCH (a:Author)-[:WROTE]->(p:Post)\nWITH a, count(p) AS posts\nWHERE posts = 1\nRETURN a.name" },
  explain: "You cannot put `WHERE` on an aggregate straight after `MATCH`, because the totals do not exist yet. `WITH` works them out and passes them on, and the `WHERE` after it filters on them, like `HAVING` in SQL." },

w5merge: { title: "restocking items",
  setup: "CREATE (:Item {sku: 'A1', qty: 5}),\n       (:Item {sku: 'C3', qty: 0})",
  sol: "MERGE (i:Item {sku: 'B2'})\nON CREATE SET i.qty = 10\nON MATCH SET i.qty = i.qty + 10",
  checks: [["MATCH (i:Item) RETURN i.sku, i.qty ORDER BY i.sku", "A1, 5; B2, 10; C3, 0"]],
  write: { task: "Restock the item `'B2'` with one `MERGE` on an `Item` node with that `sku`. If no such node exists, create it with `qty` set to 10 (`ON CREATE SET`). If it exists, add 10 to its `qty` (`ON MATCH SET`). B2 is not in the graph yet, so afterwards it has 10.", starter: "MERGE " },
  fill: { code: "___ (i:Item {sku: 'B2'})\n___ SET i.qty = 10\nON MATCH SET i.qty = i.qty + 10", blanks: [["MERGE", "merge"], ["ON CREATE", "on create"]] },
  predict: { code: "MERGE (i:Item {sku: 'A1'})\nON CREATE SET i.qty = 1\nON MATCH SET i.qty = i.qty - 1\nRETURN i.qty" },
  explain: "`MERGE` finds the node if it is there and creates it if not. `ON CREATE SET` gives a brand new node its starting values, while `ON MATCH SET` updates a node that was already there. Exactly one of the two runs." },

w5optional: { title: "authors and book counts",
  setup: "CREATE (eve:Author {name: 'Eve'}),\n       (:Author {name: 'Gil'}),\n       (hana:Author {name: 'Hana'}),\n       (eve)-[:WROTE]->(:Book {title: 'Salt'}),\n       (eve)-[:WROTE]->(:Book {title: 'Ash'}),\n       (hana)-[:WROTE]->(:Book {title: 'Reed'})",
  sol: "MATCH (a:Author)\nOPTIONAL MATCH (a)-[:WROTE]->(b:Book)\nRETURN a.name, count(b) AS books\nORDER BY a.name",
  checks: [["@result", "Eve, 2; Gil, 0; Hana, 1"]],
  write: { task: "Return two columns, every author's `name` then how many books they `WROTE`, as `books`, sorted by `name`. Authors with no books must still appear, with `0`, for example `Gil, 0`.", starter: "MATCH (a:Author)\n" },
  fill: { code: "MATCH (a:Author)\n___ (a)-[:WROTE]->(b:Book)\nRETURN a.name, count(b) AS books\nORDER BY a.name", blanks: [["OPTIONAL MATCH", "optional match"]] },
  predict: { code: "MATCH (a:Author)-[:WROTE]->(b:Book)\nRETURN a.name, count(b)\nORDER BY a.name",
    ask: "This uses a plain `MATCH`. What does it return? Write the rows like `Ann, 3`, separated by semicolons." },
  explain: "With a plain `MATCH`, Gil has no `WROTE` relationship and vanishes. `OPTIONAL MATCH` keeps him with `b` as null, and `count(b)` skips the null, so he gets 0. This is the graph version of a `LEFT JOIN`." },

w5setRemove: { title: "closing rooms for repair",
  setup: "CREATE (:Room:Bookable {number: 101, status: 'open', needsRepair: true}),\n       (:Room:Bookable {number: 102, status: 'open', needsRepair: false}),\n       (:Room:Bookable {number: 103, status: 'open', needsRepair: true})",
  sol: "MATCH (r:Room)\nWHERE r.needsRepair = true\nSET r.status = 'closed'\nREMOVE r:Bookable",
  checks: [
    ["MATCH (r:Room) RETURN r.number, r.status, labels(r) ORDER BY r.number", "101, closed, [Room]; 102, open, [Room, Bookable]; 103, closed, [Room]"]],
  write: { task: "In one query, find every `Room` whose `needsRepair` is `true`, set its `status` to `'closed'`, and remove its `Bookable` label. Other rooms stay as they are.", starter: "MATCH (r:Room)\n" },
  fill: { code: "MATCH (r:Room)\nWHERE r.needsRepair = true\n___ r.status = 'closed'\n___ r:Bookable", blanks: [["SET", "set"], ["REMOVE", "remove"]] },
  predict: { code: "MATCH (r:Room {number: 102})\nREMOVE r.status\nRETURN r.number, r.status" },
  explain: "`SET r.status = 'closed'` overwrites a property, and `REMOVE r:Bookable` takes a label off the node while keeping the node. After `REMOVE r.status`, reading that property gives null." },

w5delete: { title: "clearing old events",
  setup: "CREATE (a:Venue {name: 'Hall'}),\n       (b:Venue {name: 'Park'}),\n       (e1:Event {name: 'Fair', year: 2018}),\n       (e2:Event {name: 'Gig', year: 2025}),\n       (e3:Event {name: 'Quiz', year: 2019}),\n       (e1)-[:HELD_AT]->(a),\n       (e2)-[:HELD_AT]->(a),\n       (e3)-[:HELD_AT]->(b)",
  sol: "MATCH (e:Event)\nWHERE e.year < 2020\nDETACH DELETE e",
  checks: [
    ["MATCH (e:Event) RETURN e.name", "Gig"],
    ["MATCH (v:Venue) RETURN count(v)", "2"],
    ["MATCH ()-[h:HELD_AT]->() RETURN count(h)", "1"]],
  write: { task: "Delete every `Event` node whose `year` is before 2020, together with its `HELD_AT` relationships, in one query. The `Venue` nodes must stay.", starter: "MATCH (e:Event)\n" },
  fill: { code: "MATCH (e:Event)\nWHERE e.year < 2020\n___ e", blanks: [["DETACH DELETE", "detach delete"]] },
  predict: { code: "MATCH (:Event)-[h:HELD_AT]->(:Venue {name: 'Hall'})\nDELETE h;\n\nMATCH (e:Event)\nRETURN count(e)",
    ask: "The first statement deletes the `HELD_AT` relationships to the Hall. How many `Event` nodes does the second one count?" },
  explain: "`DETACH DELETE` first cuts every relationship of the node and then deletes it, so it works even when the node is connected. The nodes at the other end (the venues) are untouched. Plain `DELETE` on a relationship removes only that relationship." },

w5friendsOfFriends: { title: "two stops away",
  setup: "CREATE (ashby:Station {name: 'Ashby'}),\n       (brook:Station {name: 'Brook'}),\n       (cole:Station {name: 'Cole'}),\n       (dale:Station {name: 'Dale'}),\n       (eden:Station {name: 'Eden'}),\n       (fern:Station {name: 'Fern'}),\n       (ashby)-[:LINE_TO]->(brook),\n       (ashby)-[:LINE_TO]->(cole),\n       (brook)-[:LINE_TO]->(cole),\n       (brook)-[:LINE_TO]->(dale),\n       (cole)-[:LINE_TO]->(eden),\n       (cole)-[:LINE_TO]->(dale),\n       (dale)-[:LINE_TO]->(fern)",
  sol: "MATCH (start:Station {name: 'Ashby'})-[:LINE_TO]->(:Station)-[:LINE_TO]->(stop:Station)\nWHERE NOT EXISTS { (start)-[:LINE_TO]->(stop) }\nRETURN DISTINCT stop.name\nORDER BY stop.name",
  checks: [["@result", "Dale; Eden"]],
  write: { task: "Follow the `LINE_TO` arrows in their direction. Find the stations you reach from `'Ashby'` in exactly two `LINE_TO` steps but that Ashby has no direct `LINE_TO` arrow to. Return one column, each station's `name` once, sorted by name.", starter: "MATCH (start:Station {name: 'Ashby'})" },
  fill: { code: "MATCH (start:Station {name: 'Ashby'})-[:LINE_TO]->(:Station)-[:LINE_TO]->(stop:Station)\nWHERE ___ { (start)-[:LINE_TO]->(stop) }\nRETURN ___ stop.name\nORDER BY stop.name", blanks: [["NOT EXISTS", "not exists"], ["DISTINCT", "distinct"]] },
  predict: { code: "MATCH (:Station {name: 'Brook'})-[:LINE_TO]->(:Station)-[:LINE_TO]->(s:Station)\nRETURN s.name\nORDER BY s.name" },
  explain: "Two relationships in a row in one pattern make a two-step journey. `NOT EXISTS { ... }` removes the stations Ashby already reaches in one step (Cole). `DISTINCT` lists Dale once, although you can reach it through both Brook and Cole." },

w5union: { title: "players and coaches",
  setup: "CREATE (ali:Person {name: 'Ali'}),\n       (bea:Person {name: 'Bea'}),\n       (reds:Team {name: 'Reds'}),\n       (blues:Team {name: 'Blues'}),\n       (ali)-[:PLAYS_FOR]->(reds),\n       (ali)-[:COACHES]->(blues),\n       (bea)-[:COACHES]->(reds),\n       (bea)-[:COACHES]->(blues)",
  sol: "MATCH (p:Person)-[:PLAYS_FOR]->(:Team)\nRETURN p.name AS name, 'Player' AS job\nUNION\nMATCH (p:Person)-[:COACHES]->(:Team)\nRETURN p.name AS name, 'Coach' AS job",
  checks: [["@result", "Ali, Player; Ali, Coach; Bea, Coach"]],
  write: { task: "Use `UNION` to return two columns, `name` and `job`: everyone who `PLAYS_FOR` a `Team` with the job `'Player'`, and everyone who `COACHES` one with the job `'Coach'`. Each name and job pair appears once, for example `Bea, Coach`. Any row order.", starter: "MATCH (p:Person)-[:PLAYS_FOR]->(:Team)\n" },
  fill: { code: "MATCH (p:Person)-[:PLAYS_FOR]->(:Team)\nRETURN p.name AS name, 'Player' AS job\n___\nMATCH (p:Person)-[:COACHES]->(:Team)\nRETURN p.name AS name, 'Coach' ___ job", blanks: [["UNION", "union"], ["AS", "as"]] },
  predict: { code: "MATCH (p:Person)-[:PLAYS_FOR]->(:Team)\nRETURN p.name AS name\nUNION\nMATCH (p:Person)-[:COACHES]->(:Team)\nRETURN p.name AS name",
    ask: "What does it return? Write the rows in any order, separated by semicolons." },
  explain: "`UNION` joins the rows of both queries and drops exact duplicate rows: Bea coaches two teams but appears once. Both halves must use the same column names (`name`, `job`) in the same order. Use `UNION ALL` to keep duplicates." },
};
if (typeof module !== "undefined") module.exports = { SRC, TWINS };
